/// A fragment isn't a Rust type: the merge reads fragments as JSON. Its TypeScript is written
/// here.
const FRAGMENT: &str = r#"/**
 * A fragment: what one agent of a split run writes (the skeleton, an area, or the seam pass's
 * input). `version` (the one this schema.ts was generated for) and any subset of an analysis's
 * other fields, each list holding whole elements, plus the hints it leaves for the seam pass. The
 * merge leaves out a fragment with no `version`. An area's purposes carry only `id` and the
 * members it found (`serves`, `carries`, walks); an area can't create a purpose or a rule, it
 * hints one (the merge turns one it writes anyway into a hint). Claim IDs are local to the
 * fragment and unique in it: the merge renumbers them.
 */
export type Fragment = Pick<Analysis, "version"> & Partial<Omit<Analysis, "purposes" | "version">> & {
  purposes?: (Pick<Purpose, "id"> & Partial<Purpose>)[];
  hints?: Array<Hint>;
};
"#;

/// The names of the types an upload is made of: [`crate::Analysis`] and every type it reaches.
/// The split procedure's types (`split.json`, hints, fragments), the previous analysis's skeleton
/// and the report aren't among them: they never reach storage, so changing them needs no
/// migration.
pub fn upload_types() -> HashSet<String> {
    let cfg = &Config::new();
    let mut reached = Vec::new();
    collect::<crate::schema::Analysis>(cfg, &mut HashSet::new(), &mut reached);
    reached.into_iter().collect()
}

/// A body's shape: without comments or blank space, declarations sorted, so editing a doc comment
/// (a prompt change) or moving a type leaves it alone.
pub fn shape(body: &str) -> String {
    let mut out = String::with_capacity(body.len());
    let mut rest = body;
    while !rest.is_empty() {
        if let Some(after) = rest.strip_prefix("/*") {
            rest = after.find("*/").map_or("", |i| &after[i + 2..]);
        } else if let Some(after) = rest.strip_prefix("//") {
            rest = after.find('\n').map_or("", |i| &after[i..]);
        } else if let Some(after) = rest.strip_prefix('"') {
            // A string literal, kept whole: a `//` inside one is no comment.
            let end = after.find('"').map_or(after.len(), |i| i + 1);
            out.push('"');
            out.push_str(&after[..end]);

/// Word pairs that do the same.
const PHRASES: &[[&str; 2]] = &[
    ["could", "instead"],
    ["risk", "of"],
    ["well", "designed"],
    ["similar", "to"],
    ["same", "as"],
];

/// The first judging or comparing word or phrase in `text`, as written there.
pub(crate) fn judging(text: &str) -> Option<String> {
    let lower = text.to_lowercase();
    let words: Vec<&str> = lower
        .split(|c: char| !(c.is_alphanumeric() || c == '\'' || c == '’'))
        .filter(|w| !w.is_empty())
        .collect();
    for (i, w) in words.iter().enumerate() {
        let w = w.replace('’', "'");
        if WORDS.contains(&w.as_str()) {
            return Some(w);
        }
        if let Some(next) = words.get(i + 1)
            && PHRASES.iter().any(|[a, b]| *a == w && b == next)
        {
            return Some(format!("{w} {next}"));
        }
    }
    None
}

/// Validates an analysis given as JSON text.
pub fn validate(text: &str, ctx: &Context, reader: Option<&dyn Reader>) -> Outcome {
    match serde_json::from_str::<Value>(text) {
        Ok(v) => validate_value(v, ctx, reader),
        Err(e) => {
            let mut report = Report::default();
            report.error("", rule::SHAPE_JSON, format!("not JSON: {e}"));
            Outcome {
                report,
                analysis: None,
                from_version: None,
                renames: Vec::new(),
            }
        }
    }
}

let migrated = match chain.migrate(value) {
    Ok(m) => m,
    Err(e) => {
        let r = match e {
            MigrateError::Step { .. } => rule::MIGRATION_FAILED,
