        match self.0.kind(side(s), path).as_deref() {
            Some("file") => Some(EntryKind::File),
            Some("dir") => Some(EntryKind::Dir),
            _ => None,
        }
    }

    fn tracked(&self, s: CodeSide) -> Option<Vec<String>> {
        self.0
            .tracked(side(s))
            .and_then(|j| serde_json::from_str(&j).ok())
    }
}

