/** The reader the crate calls: repo-relative paths inside each checkout, nothing outside it. */
function checkouts(roots) {
  const at = (side, path) => {
    const root = roots[side];
    const full = join(root, path);
    const rel = relative(root, full);
    if (rel.startsWith("..") || isAbsolute(rel)) return undefined;
    return full;
  };
  return {
    read(side, path) {
      const p = at(side, path);
      try {
        return p === undefined ? undefined : readFileSync(p, "utf8");
      } catch {
        return undefined;
      }
    },
    kind(side, path) {
      const p = at(side, path);
      try {
        return p === undefined ? undefined : statSync(p).isDirectory() ? "dir" : "file";
      } catch {
        return undefined;
      }

    // The files git tracks in the checkout, relative to it: folder counts read these, so
    // untracked and ignored folders (node_modules, build output) never count.
    tracked(side) {
      try {
        // Git's own variables would point it at another repo than the checkout's.
        const env = { ...process.env };
        for (const k of ["GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_COMMON_DIR"]) delete env[k];
        const out = execFileSync("git", ["-C", roots[side], "ls-files", "-z"], {
          encoding: "utf8",
          env,
          maxBuffer: 1 << 30,
          stdio: ["ignore", "pipe", "ignore"],
        });
        const files = out.split("\0").filter((f) => f !== "");
        // None tracked: the folder isn't a checkout of its own (it may sit untracked inside
        // another repo), so there's no count rather than a count of 0.
        return files.length === 0 ? undefined : JSON.stringify(files);
      } catch {
        return undefined;
      }
    },
  };
}

