impl<T> Shown<T> {
    /// The same answer about another thing: what [`Shown::It`] holds, mapped.
    pub fn map<U>(self, f: impl FnOnce(T) -> U) -> Shown<U> {
        match self {
            Shown::It(t) => Shown::It(f(t)),
            Shown::Moved => Shown::Moved,
            Shown::Gone => Shown::Gone,
        }
    }
}

