    if (file && !/\.(rs|sql|toml)$|Cargo\.lock$/.test(file)) return;
    clearTimeout(timer);
    timer = setTimeout(go, 300);
  };
  watch(join(ROOT, "crates"), { recursive: true }, (_, f) => changed(f));
